 public static void sync(File d)throws IOException{try{FileDescriptor fd=Os.open(d.getPath(),OsConstants.O_RDONLY,0);try{Os.fsync(fd);}finally{Os.close(fd);}}catch(Exception e){throw new IOException("JOURNAL17_DIRECTORY_FSYNC",e);}}
