 @Override public void onReceive(Context c,Intent i){String nonce=i.getStringExtra("requestNonce"),action=i.getStringExtra("operation"),encoded=i.getStringExtra("planBase64");if(!"vn.rtr.aeris.mission.JOURNAL_LIFECYCLE17".equals(i.getAction())||nonce==null||!nonce.matches("[a-f0-9]{32}")||!("PREVIEW".equals(action)||"APPLY".equals(action)||"RECOVER".equals(action))||encoded==null||encoded.length()>21848)return;final PendingResult pending=goAsync();try{IO.execute(()->{try{execute(c,nonce,action,encoded);}catch(Exception e){Log.e("AERIS_JOURNAL17_FAILURE",String.valueOf(e.getMessage()));}finally{pending.finish();}});}catch(RejectedExecutionException e){pending.finish();Log.e("AERIS_JOURNAL17_FAILURE","BUSY_NO_QUEUE");}}
 private static void execute(Context c,String nonce,String action,String encoded)throws Exception{File index=new File(c.getFilesDir(),"product-input-registry17/highwater.aj17");if(!index.isFile()&&!action.equals("APPLY")){Log.i("AERIS_JOURNAL17",new JSONObject().put("requestNonce",nonce).put("status","NON_DURABLE_REFUSED_REGISTRY_ENROLLMENT_REQUIRED").put("durableReceipt",false).put("authorityRestorable",false).toString());return;}try(JournalGuard17.Scope guard=JournalGuard17.enter(c.getFilesDir().getCanonicalFile(),new JournalAndroidBoundary17(),JournalLifecycleReceiver17::sync,256*1024)){executeLocked(c,nonce,action,encoded);}}
 private static void executeLocked(Context c,String nonce,String action,String encoded)throws Exception{JournalGuard17.require(c.getFilesDir());
  File root=c.getFilesDir().getCanonicalFile(),receipts=new File(root,"product-input-lifecycle17");if(!receipts.exists()){if(!receipts.mkdir())throw new IOException("JOURNAL17_RECEIPT_DIRECTORY");sync(root);}if(!receipts.getCanonicalFile().equals(receipts.getAbsoluteFile())||!receipts.isDirectory())throw new IOException("JOURNAL17_RECEIPT_SYMLINK");File[] existing=receipts.listFiles();int requests=0;if(existing!=null)for(File f:existing)if(f.getName().matches("request-[a-f0-9]{32}\\.json"))requests++;if(existing==null||requests>=32)throw new IOException("JOURNAL17_RECEIPT32");File output=new File(receipts,"request-"+nonce+".json");if(output.exists())throw new IOException("JOURNAL17_NONCE_REPLAY");
  JSONObject source=identity(c),result=new JSONObject().put("format","aeris-native-journal17-administrative-receipt").put("version",1).put("requestNonce",nonce).put("operation",action).put("package",c.getPackageName()).put("sourceSHA256",source.getString("sourceSHA256")).put("processEpoch",NativeInputBridge.PROCESS_EPOCH).put("pid",android.os.Process.myPid()).put("observedElapsedNs",SystemClock.elapsedRealtimeNanos()).put("authorityRestorable",false).put("actualImages",0);String failure=null;
  JournalAndroidBoundary17 boundary=new JournalAndroidBoundary17();JournalLifecycle17 storage=new JournalLifecycle17(root,JournalLifecycleReceiver17::sync,p->{},boundary);JournalRegistry17 registry=new JournalRegistry17(root,JournalLifecycleReceiver17::sync,p->{},boundary);JournalRegistry17.RequestTicket request=null;
  try{if(!ProductActivity.lifecycleCanRotate())throw new IOException("JOURNAL17_ACTIVE_CONFIGURED_PENDING_PRODUCER");byte[] bytes=java.util.Base64.getDecoder().decode(encoded);if(!java.util.Base64.getEncoder().encodeToString(bytes).equals(encoded))throw new IOException("JOURNAL17_CANONICAL_BASE64");JournalLifecycle17.Plan plan=new JournalLifecycle17.Plan(bytes);if(!plan.newSource.equals(source.getString("sourceSHA256")))throw new IOException("JOURNAL17_SELECTED_NEW_SOURCE");String installed;try(InputStream in=new FileInputStream(c.getApplicationInfo().sourceDir)){installed=WorkspaceStore.sha(WorkspaceStore.read(in,256*1024));}boolean predecessor=plan.oldAPK.equals("8bc0a7c612c010f77e3e8c66fa6126d1d6992821eafa4f88c31a598bc188b1e1")&&plan.oldSource.equals("b62de0407ac3913a62b6e073a18f9d2937d30545e911a6cf552c871adaabb64a");if(!predecessor&&!(plan.oldAPK.equals(installed)&&plan.oldSource.equals(plan.newSource)))throw new IOException("JOURNAL17_EXACT_OLD_OR_SAME_SOURCE");long[] counts=ProductStatusReceiver.lifecycleCounts(root);if(counts[0]+32768>512L*1024*1024||counts[1]+65536>160L*1024*1024)throw new IOException("JOURNAL17_WHOLE_NATIVE_QUOTA");JournalLifecycle17.Stats s=storage.preview(plan);if(s.totalBytes+32768>JournalLifecycle17.TOTAL)throw new IOException("JOURNAL17_GLOBAL64MIB_RECEIPT_RESERVE");if(!new File(root,"product-input-registry17/highwater.aj17").isFile()){if(!action.equals("APPLY")||!plan.expectedHead.equals("ROOT"))throw new IOException("JOURNAL17_EXPLICIT_FIRST_APPLY_ENROLL_REQUIRED");List<JournalRegistry17.Original> originals=new ArrayList<>();for(JournalLifecycle17.Entry e:plan.entries)originals.add(new JournalRegistry17.Original(e.generation,e.bytes,e.sha,e.disposition,e.proof));registry.enroll(originals,plan.backup,plan.receiver,plan.cold,"ROOT");}request=registry.reserveRequest(nonce,action);result.put("planSHA256",plan.sha).put("backupTARSHA256",plan.backup).put("independentReceiverSHA256",plan.receiver).put("coldAbsenceProofSHA256",plan.cold).put("lifetimeGenerationCountBefore",s.generations.size()).put("totalChargedBytesBefore",s.totalBytes);String status="PREVIEW_ONLY_NO_ARCHIVE_OR_AUTHORITY";if(!action.equals("PREVIEW"))status=storage.apply(plan,action.equals("RECOVER"));result.put("status",status).put("flightAuthorityGranted",false).put("journalLifecycle",observation(c));
  }catch(Exception e){failure=String.valueOf(e.getMessage());if(request==null){Log.i("AERIS_JOURNAL17",new JSONObject().put("requestNonce",nonce).put("status","NON_DURABLE_REFUSED_UNADMITTED_REQUEST").put("failure",failure).put("durableReceipt",false).put("authorityRestorable",false).toString());return;}result.put("status","FAILED_CLOSED_NO_AUTHORITY").put("failure",failure);}
  new JournalAndroidBoundary17().capacity(root,4096);result.put("snapshotBeforeOwnReceiptCommit",true);byte[] out=result.toString().getBytes(StandardCharsets.UTF_8);if(out.length>4096)throw new IOException("JOURNAL17_RECEIPT4K");try(FileOutputStream stream=new JournalAndroidBoundary17().exclusive(output)){stream.write(out);stream.getFD().sync();}sync(receipts);registry.commitRequest(request,"product-input-lifecycle17/"+output.getName(),out.length,WorkspaceStore.sha(out));String head=registry.inspect(null,true).head;Log.i("AERIS_JOURNAL17",new JSONObject().put("requestNonce",nonce).put("path","files/product-input-lifecycle17/"+output.getName()).put("sha256",WorkspaceStore.sha(out)).put("bytes",out.length).put("status",result.getString("status")).put("registryHead",head).put("durableReceipt",true).toString());
 }
